def solve(x):
 def merge(a,b):
  out=dict(a)
  for k,v in b.items():
   if v is None: out.pop(k,None)
   elif isinstance(v,dict): out[k]=merge(out.get(k,{}) if isinstance(out.get(k),dict) else {},v)
   else: out[k]=v
  return out
 out={}
 for layer in x["layers"]: out=merge(out,layer)
 return out

